/**
 * @agentapps/cli — shell completion script generators.
 *
 * Generates bash and zsh completion scripts that call back into the CLI
 * via `agentapps --get-completions "<partial>"` for dynamic suggestions.
 */

/**
 * Bash completion script.
 *
 * Usage: eval "$(agentapps completions bash)"
 */
export function bashCompletionScript(): string {
  // eslint-disable-next-line no-useless-escape
  return `\
# agentapps bash completion — generated by agentapps completions bash
# Add to ~/.bashrc or ~/.bash_profile:
#   eval "$(agentapps completions bash)"

_agentapps_completions() {
    local partial=""
    local i
    for ((i=1; i <= COMP_CWORD; i++)); do
        if ((i > 1)); then
            partial+=" "
        fi
        partial+="\${COMP_WORDS[i]}"
    done

    local IFS=$'\\n'
    COMPREPLY=( $(agentapps --get-completions "$partial" 2>/dev/null) )
}
complete -F _agentapps_completions agentapps
`;
}

/**
 * Zsh completion script.
 *
 * Usage: eval "$(agentapps completions zsh)"
 */
export function zshCompletionScript(): string {
  // eslint-disable-next-line no-useless-escape
  return `\
#compdef agentapps
# agentapps zsh completion — generated by agentapps completions zsh
# Add to ~/.zshrc:
#   eval "$(agentapps completions zsh)"

_agentapps() {
    local partial="\${(j: :)words[2,CURRENT]}"
    local -a completions
    completions=("\${(@f)$(agentapps --get-completions "$partial" 2>/dev/null)}")
    compadd -- "\${completions[@]}"
}
# compdef only exists once compinit has run (stock macOS zsh never runs it).
(( $+functions[compdef] )) || { autoload -Uz compinit && compinit -i; }
compdef _agentapps agentapps
`;
}
